import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

abstract class Employee {
    protected final String name;

    Employee(String name) {
        this.name = name;
    }

    abstract String role();

    abstract long monthlyPay();
}

class Manager extends Employee {
    private final long base, bonus;

    Manager(String name, long base, long bonus) {
        super(name);
        this.base = base;
        this.bonus = bonus;
    }

    String role() { return "Manager"; }

    long monthlyPay() {
        return base + bonus;
    }
}

class Engineer extends Employee {
    private final long base;
    private final int overtimeHours;

    Engineer(String name, long base, int overtimeHours) {
        super(name);
        this.base = base;
        this.overtimeHours = overtimeHours;
    }

    String role() { return "Engineer"; }

    long monthlyPay() {
        return base + 500L * overtimeHours;
    }
}

class Intern extends Employee {
    private final long stipend;

    Intern(String name, long stipend) {
        super(name);
        this.stipend = stipend;
    }

    String role() { return "Intern"; }

    long monthlyPay() {
        return stipend;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Employee> staff = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String kind = sc.next();
            String name = sc.next();
            if (kind.equals("M")) staff.add(new Manager(name, sc.nextLong(), sc.nextLong()));
            else if (kind.equals("E")) staff.add(new Engineer(name, sc.nextLong(), sc.nextInt()));
            else staff.add(new Intern(name, sc.nextLong()));
        }
        long total = 0;
        for (Employee e : staff) {
            System.out.println(e.name + " (" + e.role() + "): " + e.monthlyPay());
            total += e.monthlyPay();
        }
        System.out.println("Total payroll: " + total);
    }
}
